export function renderFoundation(view){const labels={today:['Today foundation','The new shell is isolated and ready for the real Today composition. No demo progress, forecast, or scheduling claim is rendered here.'],plan:['Plan foundation','Plan will render dated intention and real Capacity arithmetic from existing contracts.'],goals:['Goals foundation','Goals remain long-term direction and real planning objects.'],progress:['Progress foundation','Progress will show factual recorded evidence, never planned work as completed work.'],insights:['Insights foundation','Insights stay evidence-gated and will not fabricate causation.'],wellness:['Wellness foundation','Wellness Boost practices remain separate from Wellbeing observations.'],journal:['Journal foundation','Journal remains reflection and writing, independent from Progress facts.'],settings:['Settings foundation','Settings will own presentation preferences and data/access controls, not business-domain logic.']};const [title,copy]=labels[view]||labels.today;return `<div class="foundation-state"><section class="living-surface foundation-hero"><p class="eyebrow">Experience 2 · Ambient Luxury</p><h2>${title}</h2><p>${copy}</p></section><div class="foundation-grid"><article class="static-surface foundation-card"><span class="metric-label">Presentation</span><strong>Independent frontend</strong><p>Separate HTML, CSS, JavaScript, PWA scope, cache namespace, and preferences.</p></article><article class="static-surface foundation-card"><span class="metric-label">Data</span><strong>Preview 2 only</strong><p>The experience will use the shared Preview 2 backend and D1, never Preview 1 or Production data.</p></article><article class="static-surface foundation-card"><span class="metric-label">Semantics</span><strong>Contracts first</strong><p>Daily Plan is intention. Progress is fact. Capacity is arithmetic.</p></article></div></div>`}
